function bottle(variant=0){const bg=['#e6edd7','#ede6d7','#dce5dd','#e8e0d4'][variant%4],b=['#63816c','#b78954','#596f65','#a89275'][variant%4];return `<svg viewBox="0 0 400 400" preserveAspectRatio="xMidYMid slice" xmlns="http://www.w3.org/2000/svg"><defs><linearGradient id="g${variant}" x1="0" x2="1"><stop stop-color="#fff"/><stop offset=".3" stop-color="${b}"/><stop offset="1" stop-color="#314d3c"/></linearGradient><linearGradient id="bg${variant}" x2="1" y2="1"><stop stop-color="#fcfcf4"/><stop offset="1" stop-color="${bg}"/></linearGradient></defs><rect width="400" height="400" fill="url(#bg${variant})"/><path d="M-40 210 270-50h72L-40 310Z" fill="white" opacity=".28"/><ellipse cx="201" cy="343" rx="90" ry="12" fill="#566445" opacity=".11"/><rect x="72" y="325" width="252" height="80" rx="9" fill="#f6f6eb"/><path d="M306 317q-6-82 51-122-8 80-51 122" fill="#80936c" opacity=".44"/><path d="M310 325q19-95 49-114" stroke="#7e966e" fill="none"/><g transform="rotate(${variant===1?-9:variant===3?8:0},200,250)"><rect x="157" y="149" width="88" height="180" rx="15" fill="url(#g${variant})"/><rect x="164" y="108" width="74" height="57" rx="7" fill="#344c3d"/><path d="M174 111v49m6-49v49m6-49v49m6-49v49m6-49v49m6-49v49m6-49v49m6-49v49m6-49v49m6-49v49" stroke="#70816a" opacity=".5"/><rect x="166" y="203" width="70" height="90" rx="2" fill="#f5f1df"/><text x="201" y="226" text-anchor="middle" fill="#405540" font-family="Georgia" font-size="10" letter-spacing="2">BOTANIC</text><path d="M184 238h34" stroke="#afba9b"/><text x="201" y="258" text-anchor="middle" fill="#5a6e55" font-family="Georgia" font-size="8">DAILY SERUM</text><text x="201" y="280" text-anchor="middle" fill="#939d85" font-size="6">30 ml / 1 fl. oz.</text><path d="M164 176v20m0 109v8" stroke="white" stroke-width="3" opacity=".35"/></g><text x="24" y="374" fill="#b0b8a7" font-size="8" letter-spacing="2">PRODUCT VISUAL · DEMO</text></svg>`}
function scene(n=0){const spots=[[630,246,352,630],[1745,246,355,632],[1374,246,355,632],[998,935,355,344]];const p=spots[n%4];return `<svg viewBox="${p.join(' ')}" preserveAspectRatio="xMidYMid slice"><image href="assets/reference-assets.png" width="2560" height="1279"/></svg>`}
