function review(){const titles={create:['01','创意生成','增加图片模式 · 生成数量 · 结果标识'],assets:['02','资产库','按媒体类型筛选 · 图片与视频统一管理'],tasks:['03','我的任务','二级类型筛选 · 批量生成任务与结果状态']},t=titles[page];return `<header class="review"><div class="review-left"><span class="review-num">${t[0]}</span><div><h1>${t[1]}</h1><p>${t[2]}</p></div></div><nav class="reviewnav"><span class="infolabel">产品原型 V1.0</span><a href="prototype.html?page=create" class="${page==='create'?'active':''}">创意生成</a><a href="prototype.html?page=assets" class="${page==='assets'?'active':''}">资产库</a><a href="prototype.html?page=tasks" class="${page==='tasks'?'active':''}">我的任务</a></nav></header>`}
function sidebar(){return `<aside class="sidebar"><div class="brand"><svg viewBox="0 0 36 36" fill="none" stroke="currentColor" stroke-width="2.3"><path d="M29 9a14 14 0 0 0-23 7M7 27a14 14 0 0 0 23-7M2 19h10l5-11 5 20 4-9h8"/></svg>CreatiSignal</div>${[['home','首页'],['chart','洞察'],['search','发现'],['star','创作'],['tool','工具'],['box','资产'],['task','任务'],['settings','设置']].map(([i,label])=>`<div class="navitem ${page==='create'&&label==='创作'||page==='tasks'&&label==='任务'?'selected':''}">${icon(i)}${label}${['洞察','发现','创作','工具','资产','设置'].includes(label)?'<span class="down">⌄</span>':''}</div>${label==='资产'&&page==='assets'?'<div class="navitem sub">商品库</div><div class="navitem sub selected">我的创意</div>':''}`).join('')}<div class="navbottom"><div class="balance"><span style="color:#43b7a9">♛ 升级</span><b>✦ 6,447</b></div><div class="user"><span><span class="avatar">L</span>Ice Lee</span><span>⌄</span></div></div></aside>`}
function footer(notes){return `<section class="fig-notes">${notes.map((n,i)=>`<div class="note"><span class="dot">${i+1}</span><div><b>${n[0]}</b>${n[1]}</div></div>`).join('')}</section><div class="footline"><span>CREATISIGNAL · 图片生成需求原型</span><span>界面素材仅作示意 · 交互与积分采用需求方案 · 2026.09.20</span></div>`}
function selectBox(label,value,options,handler,outline=false,ico=''){return `<div class="selectwrap ${outline?'outline':''}">${ico?icon(ico):''}<select aria-label="${label}" onchange="${handler}">${options.map(x=>`<option ${x===value?'selected':''}>${x}</option>`).join('')}</select></div>`}
function art(a){return a.type==='image'?bottle(a.art):scene(a.art)}
function assetCard(a,history=false){return `<article class="assetcard" role="button" tabindex="0" aria-label="预览${a.type==='image'?'图片':'视频'}：${a.name}" onclick="preview(${a.id})" onkeydown="if(event.key==='Enter')preview(${a.id})"><div class="cover">${art(a)}${badge(a.type)}${a.type==='video'?'<span class="play">▶</span><span class="duration">00:15</span>':''}</div><h3>${a.name}</h3><div class="assetmeta"><span>${history?'09/20 14:36':a.model}</span><span>${history?'已完成':'09/20 14:36'}</span></div></article>`}
function creator(){let d=state.drafts[state.mode],im=state.mode==='image',unit=im?'张':'条',unitCost=im?(d.model==='Wan3.0'?{ '1K':3,'2K':3,'4K':4}:{'1K':5,'2K':8,'4K':10})[d.res]:150,total=unitCost*d.qty;return `<div class="canvas creator">${sidebar()}<main class="workspace"><div class="promo"><span class="gift">✦</span><div><strong>1 折福利限时开抢！</strong><small>9 元首充＋企业认证，解锁更多创意素材</small></div><button onclick="toast('原型展示：充值入口')">立即充值</button></div><header class="hero"><h2>创意助手</h2><p>添加商品与参考素材，轻松生成图片和视频广告</p></header><section class="composer"><div class="composertabs"><span class="on">创意生成</span><span>创意报告</span><span>创意分析</span><span>创意脚本</span></div><div class="inputrow"><div class="references"><div class="ref">${bottle(0)}<small>商品图1</small></div><button class="ref addref" onclick="toast('原型展示：选择数字人人像')">${icon('person')}<small>数字人</small></button></div><div class="prompt"><b>创意 Tips <span style="color:#a2aaa0;margin-left:5px">ⓘ</span></b><textarea aria-label="创意描述" oninput="state.drafts[state.mode].prompt=this.value">${esc(d.prompt)}</textarea></div></div><div class="paramrow"><span class="dot mini">1</span>${selectBox('生成类型',im?'图片生成':'视频生成',['视频生成','图片生成'],"setMode(this.value)",true,im?'image':'video')}<span class="divider"></span>${selectBox('生成模型',d.model,im?['Wan3.0','GPT Image 2','GPT Image 2.5']:['Seedance 2.0'],"setDraft('model',this.value)",false,'star')}${selectBox('分辨率',d.res,im?['1K','2K','4K']:['720P'],"setDraft('res',this.value)")}${!im?'<span class="minorparam">Hook 模板 ⌄</span><span class="minorparam">◷ 15s</span><span class="minorparam">▯ 9:16</span><span class="minorparam">♩ 开启声音</span>':''}<span class="metaend">1 个参考素材</span></div><div class="batchrow"><span class="dot mini">2</span><span class="batchlabel">生成数量</span><div class="qtybuttons" role="group" aria-label="生成数量">${Array.from({length:im?4:3},(_,i)=>`<button class="${d.qty===i+1?'on':''}" aria-pressed="${d.qty===i+1}" onclick="setDraft('qty',${i+1})">${i+1}${unit}</button>`).join('')}</div><div class="bill">${unitCost}积分/${unit} × ${d.qty}${unit}<small>${im?'按成功生成的图片结算':'每条15秒 · 10积分/秒'}</small></div><button class="generate" onclick="toast('原型演示：'+state.drafts[state.mode].qty+'${unit}生成任务已提交；不调用真实模型、不扣积分')">${icon('star')}生成 ${d.qty}${unit} · ${total}积分</button></div></section><section class="history"><div class="historyhead"><strong>最近任务 <span class="dot mini" style="margin-left:7px">3</span></strong><a href="prototype.html?page=tasks">查看全部 ›</a></div><div class="historygrid">${[assets[0],assets[1],assets[2],assets[3]].map(a=>assetCard(a,true)).join('')}</div></section></main></div><div class="default-sample"><div class="samplelabel"><b>视频默认态</b>首次进入仍为视频生成</div><div class="samplebar"><span class="sampletype">▣ 视频生成 ⌄</span><span>Seedance 2.0 ⌄</span><span>720P ⌄</span><span>◷ 15s</span><span>▯ 9:16</span><div class="sampleqty">生成数量 <span class="on">1条</span><span>2条</span><span>3条</span></div><span class="samplebutton">生成 1条 · 150积分</span></div></div>${footer([['类型放在模型前','下拉提供视频生成 / 图片生成，默认视频；切换时更新模型与适用参数。'],['数量与总价同步','图片1–4张，视频1–3条。例：2K图片8积分/张，3张共24积分。'],['结果增加媒体标签','图片和视频都展示图标＋文字；视频保留播放和时长，图片打开大图。']])}`}
function assetsPage(){let matched=state.assetTab==='创意生成'?assets.filter(a=>(state.assetType==='all'||state.assetType===a.type)&&a.name.includes(state.assetSearch)):[];return `<div class="canvas"><main class="workspace"><div class="pagehead"><div><h2>资产库</h2><p>沉淀创意图片、视频与分析成果，持续积累可用素材</p></div><span class="infolabel">我的创意</span></div><div style="display:flex;justify-content:space-between;align-items:center"><div class="tabs">${['创意生成','创意报告','创意分析','创意脚本'].map((x,i)=>`<button class="tab ${state.assetTab===x?'on':''}" onclick="setAssetTab('${x}')">${icon(i?'task':'star')}${x}</button>`).join('')}</div>${searchBox('搜索资产',state.assetSearch,'搜索名称关键词',"state.assetSearch=this.value;renderAssetsResults()")}</div>${state.assetTab==='创意生成'?`<div class="assetbar"><div style="display:flex;align-items:center;gap:12px"><span class="dot mini">1</span><div class="segments" role="group" aria-label="资产媒体类型">${[['all','全部'],['video','视频'],['image','图片']].map(([v,t])=>`<button class="${state.assetType===v?'on':''}" onclick="setAssetType('${v}')">${v!=='all'?icon(v):''}${t}</button>`).join('')}</div></div><span class="smallnote" id="assetCount">共 ${matched.length} 项资产</span></div>`:'<div class="assetbar"><span class="smallnote">当前页签沿用原有内容</span></div>'}<section class="assetgrid" id="assetGrid">${assetResults(matched)}</section></main>${sidebar()}</div>${footer([['新增媒体筛选','在创意生成页签内增加「全部 / 视频 / 图片」，默认全部，与名称搜索共同生效。'],['混合素材清晰可辨','每个卡片固定展示媒体标签；视频显示播放与时长，图片不展示视频控件。'],['每个成功结果独立入库','一次生成4张图片，成功4张则显示4项资产；失败结果留在任务中查看。']])}`}
function assetResults(a){return a.length?a.map(x=>assetCard(x)).join(''):`<div class="empty"><b>暂无${state.assetType==='image'?'图片':state.assetType==='video'?'视频':''}资产</b>换个筛选条件，或前往创意生成创建素材。</div>`}
function searchBox(label,value,placeholder,action){return `<label class="search">${icon('search')}<input aria-label="${label}" placeholder="${placeholder}" value="${esc(value)}" oninput="${action}"></label>`}
function taskMatches(){return tasks.filter(t=>(state.taskType==='全部任务'||(t.category||'创意生成')===state.taskType)&&(state.taskMedia==='all'||t.type===state.taskMedia)&&t.name.includes(state.taskSearch))}
function taskCard(t){const cls=t.status==='部分成功'?'partial':['排队中','生成中'].includes(t.status)?'pending':'';return `<article class="taskcard" role="button" tabindex="0" aria-label="查看任务${t.id}" onclick="taskPreview(${t.id})" onkeydown="if(event.key==='Enter')taskPreview(${t.id})"><div class="taskthumb">${t.type==='image'?bottle(t.art):scene(t.art)}${t.count?`<span class="number">${t.count}${t.type==='image'?'张':'条'}</span>`:''}</div><div class="taskbody"><h3>${t.name}</h3><div class="tasktags"><span class="tasktype">${t.category||'创意生成'}</span>${t.type?badge(t.type):''}</div><div class="taskstate ${cls}"><span>${t.status}</span><span>${t.count?(t.status==='生成中'?'已完成 ':t.status==='排队中'?'等待生成 ': '成功 ')+t.done+'/'+t.count:''}</span></div><div class="taskdate">#${t.id} · 09/20 14:${String(36-(13401-t.id)).padStart(2,'0')}</div></div></article>`}
function taskResults(){let a=taskMatches();return a.length?a.map(taskCard).join(''):'<div class="empty"><b>暂无符合条件的任务</b>调整任务类型、生成类型或搜索关键词。</div>'}
function taskPage(){const disabled=!['全部任务','创意生成'].includes(state.taskType);return `<div class="canvas taskpage">${sidebar()}<main class="workspace"><header class="pagehead taskhead"><div><h2>我的任务</h2><p>查看和管理所有 AI 创意任务，包括报告、分析、脚本和创意生成</p></div><div class="taskcontrols">${searchBox('搜索任务',state.taskSearch,'搜索任务名称…',"state.taskSearch=this.value;renderTaskResults()") }<div class="filterbox"><select aria-label="任务类型" onchange="setTaskType(this.value)">${['全部任务','创意报告','创意分析','创意脚本','创意生成'].map(x=>`<option ${state.taskType===x?'selected':''}>${x}</option>`).join('')}</select></div><span class="dot mini" style="margin-right:0">1</span><div class="filterbox secondary"><select aria-label="任务生成类型" ${disabled?'disabled':''} onchange="setTaskMedia(this.value)">${[['all','全部类型'],['video','视频'],['image','图片']].map(([v,t])=>`<option value="${v}" ${state.taskMedia===v?'selected':''}>${t}</option>`).join('')}</select></div><button class="refresh" onclick="toast('已刷新，当前筛选条件保持不变')">${icon('refresh')}刷新</button></div></header><div class="task-summary"><span class="filterhint">${state.taskType} / ${state.taskMedia==='all'?'全部类型':state.taskMedia==='video'?'视频':'图片'}</span><span id="taskCount">共 ${taskMatches().length} 个任务 · 第1/1页</span></div><section class="taskgrid" id="taskGrid">${taskResults()}</section><div class="pages"><span class="off">上一页</span><span class="on">1</span><span class="off">下一页</span></div><section class="taskdetail"><div class="detailtext"><b><span class="dot mini">3</span>任务 #13401 · 部分成功</b><p>GPT Image 2.5 · 2K · 共4张<br>3张已完成，1张生成失败</p></div><div class="detailresults">${[0,1,2].map(v=>`<div class="detailthumb">${bottle(v)}</div>`).join('')}<div class="detailthumb fail"><span>!</span>生成失败</div></div><div class="detailbill">本次预扣：32积分<br>实际扣除：24积分<br><b>已退回：8积分</b></div></section></main></div>${footer([['任务类型后新增二级筛选','选项为全部类型 / 视频 / 图片；切换为报告、分析或脚本后，二级重置并禁用。'],['一次提交对应一个任务','任务展示图片或视频标签，以及4张 / 2条等数量。列表统计任务数，不是资产数。'],['多结果状态可追踪','每个任务展示完成进度；部分失败不影响已成功结果，详情明确展示退回积分。']])}`}
function render(){document.getElementById('root').innerHTML=review()+(page==='create'?creator():page==='assets'?assetsPage():taskPage());if(page==='tasks')updateTaskDetail()}
function setMode(v){state.mode=v==='图片生成'?'image':'video';render()}
function setDraft(k,v){state.drafts[state.mode][k]=v;render()}
function setAssetType(v){state.assetType=v;render()}
function setAssetTab(v){state.assetTab=v;state.assetType='all';render()}
function renderAssetsResults(){const a=state.assetTab==='创意生成'?assets.filter(a=>(state.assetType==='all'||state.assetType===a.type)&&a.name.includes(state.assetSearch)):[];document.getElementById('assetGrid').innerHTML=assetResults(a);const c=document.getElementById('assetCount');if(c)c.innerText=`共 ${a.length} 项资产`}
function setTaskType(v){state.taskType=v;if(!['全部任务','创意生成'].includes(v))state.taskMedia='all';render()}
function setTaskMedia(v){state.taskMedia=v;render()}
function updateTaskDetail(){document.querySelector('.taskdetail').style.display=taskMatches().some(t=>t.id===13401)?'flex':'none'}
function renderTaskResults(){document.getElementById('taskGrid').innerHTML=taskResults();document.getElementById('taskCount').innerText=`共 ${taskMatches().length} 个任务 · 第1/1页`;updateTaskDetail()}
let timer;function toast(s){clearTimeout(timer);const el=document.getElementById('toast');el.textContent=s;el.style.display='block';timer=setTimeout(()=>el.style.display='none',3000)}
const imageRecords={
  1:{model:'GPT Image 2.5',res:'2K',qty:4,task:13401,prompt:'使用 @商品图1 作为产品外观参考，保留绿色瓶身、瓶盖、标签和品牌标识，保持产品比例一致。\n\n将植萃精华放置在浅色石台上，搭配少量绿叶；采用浅绿色背景、柔和侧面日光，突出瓶身质感与自然投影。\n\n画面简洁，商品主体清晰，右侧留出广告文案空间。不添加额外文字、水印或其他商品。'},
  3:{model:'GPT Image 2',res:'1K',qty:2,task:13398,prompt:'参考 @商品图1，保留产品形状、标签与品牌标识。使用暖米色背景和柔和日光，制作电商商品广告图；产品略微倾斜，留出文案空间，不添加文字或水印。'},
  5:{model:'Wan3.0',res:'2K',qty:3,task:13400,prompt:'使用 @商品图1 作为商品外观参考。将精华瓶置于浅绿色背景中央，保持瓶身比例、标签和颜色一致，生成简洁的品牌展示图。不要添加文字或水印。'},
  6:{model:'GPT Image 2.5',res:'2K',qty:1,task:13396,prompt:'使用 @商品图1 作为商品外观参考。采用暖色自然光和简洁桌面场景，瓶身轻微倾斜，突出标签与产品质感。不添加文字、水印或其他商品。'}
};
function closePreview(){document.querySelector('.modal-mask')?.remove()}
function preview(id){const a=assets.find(x=>x.id===id);closePreview();if(a.type==='image'){const d=imageRecords[id];document.body.insertAdjacentHTML('beforeend',`<div class="modal-mask image-detail-mask" onclick="if(event.target===this)closePreview()"><section class="image-detail" role="dialog" aria-modal="true" aria-label="图片生成详情"><header class="image-detail-head"><div><h2>图片生成</h2><span>${esc(a.name)}</span></div><button aria-label="关闭图片详情" onclick="closePreview()">×</button></header><div class="image-detail-body"><div class="image-result"><div class="image-large" role="img" aria-label="生成图片预览">${art(a)}</div><div class="image-result-meta">${badge('image')}<span>当前查看单张生成结果</span><span class="success-label">已完成</span></div></div><aside class="image-record"><div class="record-section"><h3>提示词 <span>生成时内容</span></h3><div class="saved-prompt">${esc(d.prompt)}</div></div><div class="record-section"><h3>生成参数</h3><dl class="saved-params"><div><dt>模型</dt><dd>${d.model}</dd></div><div><dt>分辨率</dt><dd>${d.res}</dd></div><div><dt>本次生成</dt><dd>${d.qty}张</dd></div><div><dt>任务编号</dt><dd>#${d.task}</dd></div></dl></div><div class="record-section reference-section"><h3>参考素材 <span>1个</span></h3><div class="saved-reference"><div>${bottle(0)}</div><span>商品图1<small>商品外观参考</small></span></div></div><p class="record-foot">参数与提示词来自本次生成记录</p></aside></div><footer class="image-detail-actions"><span>原型示例 · 图片素材仅作界面示意</span><button class="edit-again" onclick="reuseImage(${id})">调整提示词再生成</button><button class="download-image" onclick="toast('原型示意：正式功能下载当前图片原文件')">下载</button></footer></section></div>`);return}document.body.insertAdjacentHTML('beforeend',`<div class="modal-mask" onclick="if(event.target===this)this.remove()"><section class="modal" role="dialog" aria-label="素材预览"><button class="close" aria-label="关闭预览" onclick="this.closest('.modal-mask').remove()">×</button><h3>${badge(a.type)} ${a.name}</h3><div class="modalcover">${art(a)}</div><p>${a.model} · 15秒 · 本原型仅展示视频封面，正式页沿用视频播放器<br>示意素材，非真实模型生成结果。</p></section></div>`)}
function reuseImage(id){sessionStorage.setItem('image-review-draft',JSON.stringify(imageRecords[id]));location.href='prototype.html?page=create&mode=image&reuse=1'}
function taskPreview(id){const t=tasks.find(x=>x.id===id);toast(`任务 #${id}：${t.status}${t.count?'，'+t.done+'/'+t.count+'成功':''}。部分成功详情参见下方示例。`)}
document.addEventListener('keydown',e=>{if(e.key==='Escape')closePreview()});
if(qs.get('reuse')==='1'){const saved=sessionStorage.getItem('image-review-draft');if(saved){state.drafts.image=JSON.parse(saved);state.mode='image';sessionStorage.removeItem('image-review-draft')}}
render();

if(qs.get('capture')==='1'){document.body.classList.add('capture');}
if(qs.get('detail')==='1')preview(1);
